def solve_game(initial_state):
    state = list(initial_state)
    turns = 0
    while any(state):
        k = sum(state)
        state[k-1] = 1 - state[k-1]
        turns += 1
    return turns

def get_average(n):
    total_turns = 0
    for i in range(2**n):
        state = [1 if (i >> j) & 1 else 0 for j in range(n)]
        total_turns += solve_game(state)
    return total_turns / (2**n)

for n in range(1, 8):
    print(f"A({n}) = {get_average(n)}")

